import type { HTMLAttributes, LiHTMLAttributes, ReactNode } from "react";
import { cx } from "../utils/cx";

/** A vertical sequence of events on a hairline. Server-compatible. */
export function Timeline({ className, ...rest }: HTMLAttributes<HTMLOListElement>) {
  return <ol {...rest} className={cx("hm-timeline", className)} />;
}

export type TimelineItemProps = Omit<LiHTMLAttributes<HTMLLIElement>, "title"> & {
  title: ReactNode;
  /** When it happened (a `<time>` is ideal). */
  time?: ReactNode;
  description?: ReactNode;
  status?: "done" | "current" | "upcoming";
  /** Replace the dot (an icon or an Avatar). */
  marker?: ReactNode;
};

export function TimelineItem({
  title,
  time,
  description,
  status = "done",
  marker,
  className,
  children,
  ...rest
}: TimelineItemProps) {
  return (
    <li
      {...rest}
      className={cx("hm-timeline-item", className)}
      data-status={status}
      aria-current={status === "current" ? "step" : undefined}
    >
      <span className="hm-timeline-marker" aria-hidden="true">
        {marker}
      </span>
      <div className="hm-timeline-body">
        <p className="hm-timeline-title">{title}</p>
        {time ? <span className="hm-timeline-time">{time}</span> : null}
        {description ? <p className="hm-timeline-description">{description}</p> : null}
        {children}
      </div>
    </li>
  );
}
